template:
@php
    // A tab needs its title — it is the tab — and something to show under it; a picture deleted
    // from the library resolves without an address and is left out, not printed broken.
    $shown = [];
    foreach (is_array($tabs) ? $tabs : [] as $item) {
        if (! is_array($item)) {
            continue;
        }
        $title = wx_text($item['title'] ?? null)->plain();
        $image = is_array($item['picture'] ?? null) && ! empty($item['picture']['url']) ? $item['picture'] : null;
        $body = is_string($item['text'] ?? null) ? trim($item['text']) : '';
        if ($title === '' || ($image === null && $body === '')) {
            continue;
        }
        $shown[] = ['title' => $title, 'picture' => $image, 'text' => $body];
    }
    $label = $heading ? wx_text($heading)->plain() : null;
    // A block saved before a field had a value looks as a new one does.
    $place = in_array($picture_side ?? null, ['top', 'start', 'end'], true) ? $picture_side : 'top';
    $centred = ($align ?? null) === 'center';
    $fade = ($transition ?? null) === 'fade';
@endphp
@if ($shown)
<section @class(['b-tabs', 'b-tabs--'.$place, 'b-tabs--center' => $centred]) data-wx-block="tabs">
    @if ($heading)
        <h2 class="b-tabs__heading">{{ $heading }}</h2>
    @endif
    <x-webx-tabs class="b-tabs__tabs" :label="$label" :transition="$fade ? 'fade' : null">
        @foreach ($shown as $item)
            {{-- Without JavaScript every panel stands under its title; the runtime makes the titles tabs. --}}
            <x-webx-tabs.panel :title="$item['title']" :level="$heading ? 3 : 2">
                <div @class(['b-tabs__body', 'b-tabs__body--picture' => $item['picture'] && $item['text'] !== ''])>
                    @if ($item['picture'])
                        <img class="b-tabs__picture" src="{{ $item['picture']['url'] }}" alt="{{ $item['picture']['alt'] ?? '' }}" @if ($item['picture']['width']) width="{{ $item['picture']['width'] }}" height="{{ $item['picture']['height'] }}" @endif @unless ($loop->first) loading="lazy" @endunless>
                    @endif
                    @if ($item['text'] !== '')
                        <div class="b-tabs__text">{!! $item['text'] !!}</div>
                    @endif
                </div>
            </x-webx-tabs.panel>
        @endforeach
    </x-webx-tabs>
</section>
@endif

styles:
.b-tabs {
    container-type: inline-size;
}

.b-tabs__heading {
    margin: 0 0 1em;
}

.b-tabs--center .b-tabs__heading {
    text-align: center;
}

/* Centred by the margins of the end tabs, not by justify-content: a row wider than the column
   then still scrolls from its first tab instead of cutting it off on the left. */
.b-tabs--center .webx-tabs__tab:first-child {
    margin-inline-start: auto;
}

.b-tabs--center .webx-tabs__tab:last-child {
    margin-inline-end: auto;
}

.b-tabs__body {
    display: grid;
    gap: 1em;
    align-items: start;
}

.b-tabs__picture {
    display: block;
    width: 100%;
    height: auto;
    border-radius: 0.25em;
}

.b-tabs__text {
    min-width: 0;
}

.b-tabs__text > :first-child {
    margin-top: 0;
}

.b-tabs__text > :last-child {
    margin-bottom: 0;
}

/* Beside the text where the column has room for both, above it where it has not: the width of
   the column the block stands in decides, not the window. */
@container (min-width: 40em) {
    .b-tabs--start .b-tabs__body--picture,
    .b-tabs--end .b-tabs__body--picture {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 2em;
    }

    .b-tabs--end .b-tabs__body--picture .b-tabs__picture {
        order: 1;
    }
}
